pm.test('Status code is 200', () => {
  pm.response.to.have.status(200);
});

pm.test('Returns Common Healing Potion at the expected price', () => {
  const body = pm.response.json();

  pm.expect(body.schemaVersion).to.equal(1);
  pm.expect(body.products).to.be.an('array').with.lengthOf(1);
  pm.expect(body.total).to.equal(body.products.length);

  const product = body.products[0];

  pm.expect(product.sku).to.equal('SSC-POT-0001');
  pm.expect(product.name).to.equal('Common Healing Potion');
  pm.expect(product.price).to.deep.equal({
    amount: 5,
    denomination: 'Copper',
    unit: 'ounce',
  });
});

