  const body = pm.response.json();

  pm.expect(body.error.code).to.equal('INVALID_QUERY_PARAMETER');
  pm.expect(body.error.parameter).to.equal('status');
  pm.expect(body.error.message).to.be.a('string').and.not.be.empty;
});

